/**
 * Auto-generated file detection. Pure and dependency-free so main, renderer and
 * the review engine all share one definition of "generated".
 */

/** Paths that are generated by convention — no need to look at the contents. */
const GENERATED_PATHS: RegExp[] = [
  /(^|\/)(package-lock\.json|yarn\.lock|pnpm-lock\.yaml|Cargo\.lock|composer\.lock|poetry\.lock|Gemfile\.lock)$/,
  /(^|\/)(dist|build|out|vendor|node_modules)\//,
  /\.min\.(js|css)$/,
  /\.(js|css)\.map$/,
  /\.pb\.go$/,
  /_pb2\.pyi?$/,
  /\.g\.dart$/,
  /(^|\/)__snapshots__\//,
  /\.snap$/,
  /\.generated\.|\.gen\./,
  // Static-analysis baselines: mago, phpstan, psalm, rubocop. Tool output with
  // no header comment. The `-baseline` prefix requirement keeps a hand-written
  // `baseline.yml` out of it.
  /(^|\/)[\w.-]*[-_]baseline\.(toml|neon|xml|ya?ml|json|php)$/i,
  /(^|\/)\.rubocop_todo\.ya?ml$/,
];

const MARKER = /@generated\b|\bDO NOT EDIT\b/i;

/**
 * A marker only counts in the file's leading comment block. Code that merely
 * mentions the marker — a linter, a codegen config emitting its own banner,
 * this very file — is hand-written.
 */
const COMMENT_LINE = /^\s*(\/\/|\/\*|\*|#|--|;|%|<!--|""")/;
/** Openers that legitimately sit above a generated banner. */
const PREAMBLE_LINE = /^\s*(<\?php|<\?xml|<!DOCTYPE|---)/i;
const BLANK_LINE = /^\s*$/;

/** How many leading lines of a file count as its header for marker purposes. */
const HEADER_LINES = 20;

export function isGeneratedPath(path: string): boolean {
  return GENERATED_PATHS.some((re) => re.test(path));
}

/**
 * True when the text opens with a generator banner. The marker has to sit in the
 * leading comment block: further down it's a note about one block, not a claim
 * about the file, and inside real code it's usually a tool talking *about*
 * generated output.
 */
export function hasGeneratedMarker(text: string): boolean {
  for (const line of text.split('\n', HEADER_LINES)) {
    if (COMMENT_LINE.test(line)) {
      if (MARKER.test(line)) return true;
    } else if (!BLANK_LINE.test(line) && !PREAMBLE_LINE.test(line)) {
      return false; // real code started — no banner above it
    }
  }
  return false;
}

/** Path patterns, falling back to a marker sniff when the file's head is available. */
export function isGenerated(path: string, head?: string): boolean {
  return isGeneratedPath(path) || (head !== undefined && hasGeneratedMarker(head));
}

/**
 * Generated files in a unified diff, in diff order. The marker sniff only reads
 * hunks that start at line 1 of the new file — elsewhere in the diff a
 * "DO NOT EDIT" line is a comment about one block, not a file-level claim.
 */
export function generatedInDiff(diff: string): string[] {
  const found: string[] = [];
  let path: string | null = null;
  let header: string[] | null = null;

  const flush = () => {
    if (path && isGenerated(path, header?.join('\n'))) found.push(path);
    path = null;
    header = null;
  };

  for (const line of diff.split('\n')) {
    if (line.startsWith('+++ ')) {
      flush();
      const target = line.slice(4).trim();
      path = target === '/dev/null' ? null : target.replace(/^b\//, '');
    } else if (line.startsWith('@@')) {
      // Only the hunk covering the new file's first line can hold its header.
      header = /\+1(,|\s)/.test(line) ? [] : null;
    } else if (header && header.length < HEADER_LINES && /^[+ ]/.test(line)) {
      header.push(line.slice(1));
    }
  }
  flush();
  return found;
}

/** Prompt fragment telling a reviewer to leave generated output alone. */
export function generatedFilesNote(diff: string): string {
  const paths = generatedInDiff(diff);
  if (!paths.length) return '';
  return (
    'These changed files are auto-generated — do NOT report findings inside them. Mention one only if the change indicates the generator\'s input or config is wrong:\n' +
    paths.map((p) => `- ${p}`).join('\n') +
    '\n\n'
  );
}
